<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';
import {useApplication} from '../../application';
import {useMinutesGeneration} from './useMinutesGeneration';
import {useMinutesTaskObservation} from './useMinutesTaskObservation';
import type {GenerationRegion} from '../../shared/api/minutes-generation';
import {ApiError} from '../../shared/api/client';
import Icon from '../../shared/Icon.vue';
const application=useApplication();
const props=withDefaults(defineProps<{meetingId:string;autoStart?:boolean;regionCategory?:GenerationRegion['category'];dialogPresentation?:boolean;advanced?:boolean}>(),{dialogPresentation:false,advanced:false}),{session,minutesGeneration,workspace,journals,generationScopeReady,meetingScope}=useApplication();
const emit=defineEmits<{changed:[];started:[];close:[]}>();
const actor=()=>session.current.value?.actor.enterpriseId??null,eligible=()=>generationScopeReady.value&&meetingScope.value===props.meetingId;
const state=useMinutesGeneration({...minutesGeneration,authorize:async(id,signal)=>{const nav=await workspace.navigation(id,signal);if(nav.relation!=='OWNER'||nav.navigationState!=='CHECK_PRODUCER')throw new ApiError('http',403,'当前身份或会议状态不允许生成。');return nav;}},actor,()=>props.meetingId,eligible,journals);
const localControlled=import.meta.env.DEV&&import.meta.env.VITE_LOCAL_DEV_LOGIN==='1';
const selection=ref(''),localError=ref<string|null>(null),message=computed(()=>localError.value??(state.error.value instanceof Error?state.error.value.message:null));
const stop=watch(()=>[actor(),props.meetingId,eligible()],()=>{selection.value='';localError.value=null;if(actor()&&eligible())void state.reload();},{immediate:true,flush:'sync'}),stopLogout=session.onLogout(state.logout);
const pending=computed(()=>!['EMPTY','ACKNOWLEDGED','CONFLICT','REJECTED'].includes(state.command.state.value));
const regionCategories:Record<GenerationRegion['category'],string>={OVERVIEW:'会议概述',DISCUSSION:'关键内容',CONCLUSION:'会议结论',ACTION:'行动项',RISK:'风险与阻碍',OPEN_QUESTION:'待解决问题',DISAGREEMENT:'分歧'};
const regionSelection=ref<GenerationRegion['category']>(props.regionCategory??'OVERVIEW'),instructions=ref('');
const regionMode=computed(()=>{if(pending.value&&state.command.snapshot.value){try{return JSON.parse(state.command.snapshot.value.body).scope==='REGION';}catch{return false;}}return props.regionCategory!==undefined;});
watch(()=>props.regionCategory,category=>{if(category&&!pending.value){regionSelection.value=category;instructions.value='';}});
watch(()=>state.command.snapshot.value,original=>{if(!original)return;try{const body=JSON.parse(original.body);if(body.scope==='REGION'){regionSelection.value=body.category;instructions.value=body.instructions;}}catch{/* Invalid recovery remains blocked by the command journal. */}});
const reasons:Record<string,string>={CAPABILITY_UNAVAILABLE:'纪要生成服务暂不可用，请稍后重试',TRANSCRIPT_CONFIRMATION_REQUIRED:'请先确认已保存转写',SETTINGS_REQUIRED:'请先选择初始模板与设置',MINUTES_COMBINED_NOT_INSTALLED:'纪要生成服务尚不可用',GENERATION_REQUIRED:'当前内容需要重新生成',PUBLISHED:'会议已经发布'};
async function refreshGeneration(){const who=actor(),id=props.meetingId;await state.reload();if(who===actor()&&id===props.meetingId&&eligible()&&state.current.value&&!state.error.value)emit('changed');}
function discard(){try{localError.value=null;state.discardRejected();void refreshGeneration();}catch(cause){localError.value=cause instanceof Error?cause.message:'原操作暂无法清理。';}}
let autoStarted=false,templateRequested=false;watch(()=>[actor(),props.meetingId],()=>{autoStarted=false;templateRequested=false;selection.value='';},{flush:'sync'});
const taskState=useMinutesTaskObservation(application.tasks,actor,()=>props.meetingId,()=>eligible()&&!!application.tasks,()=>{void state.reload().then(()=>emit('changed'));});
const taskLabels:Record<string,string>={READY:'等待生成',RUNNING:'正在生成纪要',RECONCILING:'正在查回生成结果',SUCCEEDED:'生成已完成',FAILED:'纪要生成失败，请重试',STALE:'生成依据已变化，请核对后重新生成',CANCELLED:'生成已取消'};
const taskMessage=computed(()=>taskState.latest.value?taskLabels[taskState.latest.value.state]:null);
watch(()=>state.current.value?.activeTaskIds.join('|'),()=>{if(state.current.value)void taskState.refresh();});
async function generate(){if(pending.value||state.busy.value||state.blocked.value||taskState.running.value||state.current.value?.activeTaskIds.length)return;localError.value=null;if(regionMode.value){const base=state.current.value?.saved.elementSetId;if(!base||!instructions.value.trim()||Array.from(instructions.value).length>4096){localError.value='请读取已保存要素并填写生成要求（最多4096字）。';return;}await state.generateRegion({baseElementSetId:base,category:regionSelection.value,instructions:instructions.value});return;}if(!state.current.value?.saved.templateRevisionId){if(!state.templates.value)await state.loadTemplates(false);if(!selection.value)selection.value=state.templates.value?.items.find(t=>t.selectable&&t.default)?.revisionId??'';if(!selection.value){localError.value='默认模板暂不可用，请选择可用模板后生成。';return;}await state.initialize(selection.value);if(state.error.value||!state.current.value?.saved.templateRevisionId)return;}await state.generate();}
watch(()=>props.autoStart,value=>{if(value)autoStarted=false;});
watch(()=>[props.autoStart,state.current.value,state.loading.value,state.busy.value,taskState.observed.value,taskState.loading.value],()=>{if(!state.current.value||state.loading.value||state.busy.value||taskState.loading.value)return;const initialResume=!props.dialogPresentation&&taskState.observed.value&&!taskState.latest.value&&!state.current.value.observation.currentMinutesRevisionId&&!!state.current.value.saved.transcriptConfirmationId&&(state.current.value.eligible||state.current.value.reasons.every(r=>r==='SETTINGS_REQUIRED'));if((props.autoStart||initialResume)&&!autoStarted&&!pending.value){autoStarted=true;void generate();}else if(!props.autoStart&&!state.current.value.saved.templateRevisionId&&!templateRequested){templateRequested=true;void state.loadTemplates(false).then(()=>{selection.value=state.templates.value?.items.find(t=>t.default&&t.selectable)?.revisionId??'';});}});
watch(()=>state.command.ack.value?.result,ack=>{if(ack?.kind==='GENERATION_TASK'){emit('started');void taskState.refresh();}});
const regionLabel=computed(()=>regionCategories[regionSelection.value]);
const generationDisabled=computed(()=>{const current=state.current.value;return !current||taskState.running.value||!!current.activeTaskIds.length||state.busy.value||state.loading.value||pending.value||state.blocked.value||regionMode.value&&(!instructions.value.trim()||Array.from(instructions.value).length>4096||!current.saved.elementSetId)||!current.eligible&&!(!current.saved.templateRevisionId&&!!selection.value&&current.reasons.every(r=>r==='SETTINGS_REQUIRED'));});
const showRecovery=computed(()=>props.advanced||pending.value||!!message.value||!!state.current.value&&!state.current.value.eligible);
function prepareOpen(category?:GenerationRegion['category']){if(pending.value||state.busy.value)return false;regionSelection.value=category??'OVERVIEW';instructions.value='';localError.value=null;return true;}
defineExpose({generate,pending,prepareOpen,regionMode,regionLabel,localControlled,recoveryVisible:showRecovery});
onUnmounted(()=>{taskState.dispose();stop();stopLogout();state.dispose();});
</script><template><section v-if="dialogPresentation" class="generation-dialog-form">
 <div class="modal-b">
  <template v-if="regionMode"><label>目标区域<select v-model="regionSelection" :disabled="pending||state.busy.value"><option v-for="(label,category) in regionCategories" :key="category" :value="category">{{label}}</option></select></label><div class="banner info" style="padding:8px 14px"><Icon name="sparkle" :size="14"/> 仅重新生成本章节，其他章节中的人工修改不会被覆盖。</div><div class="field"><label for="generation-region-instructions">局部生成要求</label><textarea id="generation-region-instructions" v-model="instructions" class="input" rows="3" maxlength="8192" :disabled="pending||state.busy.value" placeholder="例如：更突出风险指标变化，保留原有结论编号"></textarea></div></template>
  <p v-else class="muted">基于已确认的会议转写生成核心要素和会议纪要。现有正文与人工修改继续保留，完成后核对候选再决定采用。</p>
  <p v-if="state.loading.value" role="status" class="small muted">正在检查生成条件…</p>
  <p v-if="message" role="alert">{{message}}</p>
  <template v-if="state.current.value&&!state.current.value.saved.templateRevisionId"><div class="field"><label>纪要模板<select v-model="selection" class="select" :disabled="state.busy.value||pending"><option value="">请选择模板</option><option v-for="item in state.templates.value?.items" :key="item.revisionId" :value="item.revisionId" :disabled="!item.selectable">{{item.name}}{{item.default?'（默认）':''}}</option></select></label></div><button v-if="!state.templates.value" type="button" class="btn sm" :disabled="state.loading.value" @click="state.loadTemplates(false)">重新读取模板</button></template>
  <p v-if="taskMessage" role="status">{{taskMessage}}</p><p v-if="taskState.error.value" role="alert">{{taskState.error.value}} <button class="btn sm" @click="taskState.refresh">重新读取生成状态</button></p><section v-if="showRecovery" class="generation-recovery" aria-label="生成范围与状态">

   <p v-if="regionMode" class="small muted">仅采用目标区域的候选，其他区域与原正文保留；采用后正文标记为待更新。以当前确认转写和已应用材料为依据，排除设置继续生效。</p>
   <p v-if="localControlled" class="controlled-provider-note small muted">联调环境生成结果来自测试接口，请核对会议原文。</p>
   <ul v-if="state.current.value&&!state.current.value.eligible"><li v-for="reason in state.current.value.reasons.filter(r=>r!=='SETTINGS_REQUIRED')" :key="reason">{{reasons[reason]??reason}}</li></ul>
   <p v-if="pending" role="status">原请求结果待确认，请恢复原操作后继续。</p><button v-if="pending" type="button" class="btn" :disabled="state.busy.value||state.blocked.value" @click="state.retry">恢复原请求</button>
   <button v-if="['CONFLICT','REJECTED'].includes(state.command.state.value)" type="button" class="btn" :disabled="state.busy.value" @click="discard">清除已拒绝请求并重新读取</button>
   <p v-if="state.command.ack.value?.result.kind==='GENERATION_TASK'" class="small" role="status">生成任务已受理，离开后会继续处理，返回可查看结果。</p>
   <button type="button" class="btn sm" :disabled="state.loading.value||state.busy.value" @click="refreshGeneration">刷新生成条件</button>
  </section>
 </div>
 <footer class="modal-f"><button type="button" class="btn" @click="emit('close')">取消</button><button type="button" class="btn primary" :aria-label="regionMode?'开始生成区域候选':'生成完整纪要'" :disabled="generationDisabled" @click="generate">{{regionMode?'开始生成':'生成完整纪要'}}</button></footer>
</section><section v-else class="card generation-panel"><p v-if="taskMessage" class="generation-status" role="status">{{taskMessage}}</p><p v-if="taskState.error.value" role="alert">{{taskState.error.value}} <button class="btn sm" @click="taskState.refresh">重新读取生成状态</button></p><h2>{{regionMode?'局部重新生成':'生成会议纪要'}}</h2><p class="muted">{{regionMode?'仅生成所选区域的候选。采用后保留其他区域和原正文，正文将标记为待更新。':'基于已确认的会议转写生成核心要素和会议纪要。'}}</p><template v-if="regionMode"><label>目标区域<select v-model="regionSelection" :disabled="pending||state.busy.value"><option v-for="(label,category) in regionCategories" :key="category" :value="category">{{label}}</option></select></label><label>生成要求<textarea v-model="instructions" class="input" rows="5" maxlength="8192" :disabled="pending||state.busy.value" placeholder="补充关注重点、组织方式和表达要求"></textarea></label><p class="small muted">以当前确认转写和已应用背景材料为依据，排除设置继续生效。生成要求不会直接修改已有内容。</p></template><p v-if="localControlled" class="controlled-provider-note small muted">联调环境生成结果来自测试接口，请核对会议原文。</p><p v-if="message" role="alert">{{message}}</p><p v-if="state.loading.value" role="status">正在检查生成条件…</p><p v-if="pending" role="status">原请求结果待确认，请恢复原操作后继续。</p><template v-if="state.current.value"><label v-if="!state.current.value.saved.templateRevisionId">纪要模板<select v-model="selection" :disabled="state.busy.value||pending"><option value="">请选择模板</option><option v-for="item in state.templates.value?.items" :key="item.revisionId" :value="item.revisionId" :disabled="!item.selectable">{{item.name}}{{item.default?'（默认）':''}}</option></select></label><button v-if="!state.templates.value&&!state.current.value.saved.templateRevisionId" class="btn sm" :disabled="state.loading.value" @click="state.loadTemplates(false)">重新读取模板</button><ul v-if="!state.current.value.eligible"><li v-for="reason in state.current.value.reasons.filter(r=>r!=='SETTINGS_REQUIRED')" :key="reason">{{reasons[reason]??reason}}</li></ul><button class="btn primary" :disabled="generationDisabled" @click="generate">{{regionMode?'生成区域候选':'生成完整纪要'}}</button></template><p v-if="state.command.ack.value?.result.kind==='GENERATION_TASK'" class="small" role="status">生成任务已受理，离开后会继续处理，返回可查看结果。</p><details class="mt16"><summary class="small muted">状态与恢复</summary><button v-if="pending" class="btn" :disabled="state.busy.value||state.blocked.value" @click="state.retry">恢复原请求</button><button v-if="['CONFLICT','REJECTED'].includes(state.command.state.value)" class="btn" :disabled="state.busy.value" @click="discard">清除已拒绝请求并重新读取</button><button class="btn" :disabled="state.loading.value||state.busy.value" @click="refreshGeneration">刷新生成条件</button></details></section></template>
<style scoped>.generation-panel{padding:24px;margin:16px}.generation-panel h2{font-size:18px;margin:0 0 12px}.generation-panel .btn{margin-top:12px}label{display:block;margin:16px 0}select{display:block;width:100%;max-width:500px;margin-top:8px;padding:10px;font:inherit;border:1px solid var(--border2);border-radius:6px}.muted{color:var(--muted)}p{margin-top:10px;overflow-wrap:anywhere}.generation-panel ul{padding-left:20px;margin:12px 0}</style>

<style scoped>.generation-dialog-form{display:contents}.generation-dialog-form .field>label{margin:0 0 6px;font-size:12.5px;color:var(--muted);font-weight:500}.generation-dialog-form .modal-b>p:first-child{margin-top:0}.generation-recovery{border-top:1px solid var(--border);padding-top:12px;margin-top:12px}.generation-recovery>button{margin:8px 8px 0 0}.generation-recovery ul{padding-left:20px;margin-top:12px}</style>
